import { parseSource } from '../src/youtube.js';
import { PlaybackMode } from '../src/playback-mode.js';

const PANE = 'youtube';
const EMPTY_IMAGE = { rgba: 'AAAA/w==', width: 1, height: 1 };

/**
 * @typedef {import('claude-code').EngineInterface} Engine
 * @typedef {{root: string, fetch: Engine['http']['fetch'], run: Engine['process']['run'],
 * every: Engine['clock']['every'], invalidate: () => void, blit: Engine['ui']['blit'],
 * openPane: Engine['ui']['open'], closePane: Engine['ui']['close']}} Host
 * @typedef {{source: string, title: string, entries: {id: string, title: string}[],
 * index: number, status: string, error: string, audioError: string,
 * muted: boolean, playing: boolean}} Snapshot
 */

/** Keep engine calls here so Claude's static hook analyzer can discover them.
 * @param {Engine} $
 * @returns {Host}
 */
function hostOf($) {
  return {
    root: $.plugin.root,
    fetch: (url, init) => $.http.fetch(url, init),
    run: (argv, init) => $.process.run(argv, init),
    every: (ms, fn) => $.clock.every(ms, fn),
    invalidate: () => $.ui.invalidate('ui.render'),
    blit: args => $.ui.blit(args),
    openPane: args => $.ui.open(args),
    closePane: args => $.ui.close(args),
  };
}

/** @param {unknown} caught */
const errorMessage = caught => caught instanceof Error ? caught.message : String(caught);

/** @type {import('claude-code').Register} */
export const register = (on, options) => {
  const playback = new PlaybackMode();
  let supported = false;
  let socketPath = '';
  /** @type {Promise<void> | null} */
  let starting = null;
  /** @type {import('claude-code').Timer | null} */
  let timer = null;
  let polling = false;
  let fetchStartedAt = 0;
  let painting = false;
  let paintStartedAt = 0;
  let retryPaint = false;
  let fileRefusals = 0;
  let lastPaintDenial = '';
  /** @type {{frames: number, paints: number, refused: number, fetchMs: number,
   * paintMs: number, gapMs: number, lastFrameAt: number} | null} */
  let measurement = null;
  let changingSource = 0;
  let frameEpoch = 0;
  /** @type {import('claude-code').ImageSource | null} */
  let waitingImage = null;
  let stopped = false;
  let queue = Promise.resolve();
  let sequence = -1;
  /** @type {import('claude-code').ImageSource} */
  let image = EMPTY_IMAGE;
  let mounted = false;
  let input = typeof options.source === 'string' ? options.source : '';
  let error = '';
  let connectionError = '';
  let summary = '';
  /** @type {Snapshot} */
  let state = { source: '', title: '', entries: [], index: 0, status: 'empty',
    error: '', audioError: '', muted: true, playing: false };

  /** @param {Host} host @param {string} path @param {Record<string, unknown>} [command] */
  async function request(host, path, command) {
    if (!socketPath) throw new Error('Load a YouTube video or playlist first.');
    const response = await host.fetch(`http://bridge${path}`, {
      socketPath,
      ...(command ? { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(command) } : {}),
    });
    const result = JSON.parse(response.text);
    if (!response.ok) throw new Error(result.error || 'Player helper could not answer.');
    return result;
  }

  function discardWaitingFrames() {
    frameEpoch++;
    waitingImage = null;
    retryPaint = false;
    fileRefusals = 0;
  }

  /** Discard frames fetched before a source/transport change, including late
   * file refusals. Polling resumes once the helper has accepted the change.
   * @param {Host} host @param {Record<string, unknown>} command @param {boolean} [clear]
   */
  async function changeSource(host, command, clear = true) {
    discardWaitingFrames();
    sequence = -1;
    if (clear) image = EMPTY_IMAGE;
    changingSource++;
    try { await request(host, '/command', command); }
    finally { changingSource--; }
  }

  /** A blit resolves at paint time. Keep fetching independently, with at most
   * one paint outstanding and one waiting image, replaced by newer frames.
   * @param {Host} host
   */
  async function paint(host) {
    if (painting || !waitingImage || !mounted || !playback.open || stopped || !socketPath) return;
    const source = waitingImage;
    const epoch = frameEpoch;
    const sample = measurement;
    waitingImage = null;
    retryPaint = false;
    painting = true;
    paintStartedAt = Date.now();
    try {
      const result = await host.blit({ requestId: PANE, key: 'video', source })
        .catch(caught => ({ deny: errorMessage(caught) }));
      if (sample && sample === measurement) {
        sample.paintMs = Math.max(sample.paintMs, Date.now() - paintStartedAt);
        if (result?.deny || !result) sample.refused++;
        else sample.paints++;
      }
      if (epoch !== frameEpoch || stopped || !playback.open) return;
      if (!result || result.deny) {
        lastPaintDenial = result?.deny || 'Paint did not complete.';
        retryPaint = true;
      } else fileRefusals = 0;
      // Claude probes file access asynchronously. Its initial "asked now,
      // blit again" response is not a refusal of the file transport. A paused
      // first frame also needs retrying, without waiting for another frame.
      const probing = result?.deny?.includes('has not yet said whether it reads files');
      if (result?.deny && 'file' in source && !probing && ++fileRefusals >= 10) {
        // Serialize transport changes with controls. A hide/reload that wins
        // the race invalidates this refusal before it can affect the new view.
        await act(host, async () => {
          if (epoch !== frameEpoch || !playback.open) return;
          await changeSource(host, { action: 'inline' }, false);
        });
      }
    } finally {
      painting = false;
      paintStartedAt = 0;
      if (waitingImage) void paint(host);
    }
  }

  /** @param {Host} host */
  async function poll(host) {
    if (polling || changingSource || !socketPath || stopped) return;
    const epoch = frameEpoch;
    const sample = measurement;
    const startedAt = Date.now();
    fetchStartedAt = startedAt;
    polling = true;
    try {
      const snapshot = await request(host, `/state?after=${sequence}`);
      if (stopped || epoch !== frameEpoch) return;
      const { frame, sequence: nextSequence, ...nextState } = snapshot;
      if (sample && sample === measurement) {
        const now = Date.now();
        sample.fetchMs = Math.max(sample.fetchMs, now - startedAt);
        if (frame && sequence !== nextSequence) {
          sample.frames++;
          sample.gapMs = Math.max(sample.gapMs, now - sample.lastFrameAt);
          sample.lastFrameAt = now;
        }
      }
      if (frame) image = frame;
      else if (sequence !== nextSequence) image = EMPTY_IMAGE;
      const changed = sequence !== nextSequence;
      sequence = nextSequence;
      state = nextState;
      connectionError = '';
      const nextSummary = JSON.stringify(state);
      if (nextSummary !== summary) {
        summary = nextSummary;
        host.invalidate();
      }
      if ((changed || retryPaint) && mounted && playback.open) {
        waitingImage = image;
        void paint(host);
      }
    } catch (caught) {
      if (stopped || epoch !== frameEpoch) return;
      connectionError = `Player connection lost. Load the link again to reconnect. ${errorMessage(caught)}`;
      socketPath = '';
      timer?.cancel();
      sequence = -1;
      discardWaitingFrames();
      host.invalidate();
    } finally { polling = false; fetchStartedAt = 0; }
  }

  /** @param {Host} host */
  async function ensureBridge(host) {
    if (socketPath) return;
    if (!starting) {
      starting = (async () => {
        const result = await host.run(['node', `${host.root}/src/bridge.js`, 'start'], { timeoutMs: 10000 });
        if (result.exitCode !== 0) throw new Error(result.stderr || 'Cannot start player helper.');
        socketPath = JSON.parse(result.stdout).socketPath;
        // Poll faster than the 24 fps frame period so jitter does not drop frames;
        // a poll with no new frame returns a tiny reply.
        timer = host.every(16, () => { void poll(host); });
        if (stopped) {
          timer.cancel();
          await request(host, '/command', { action: 'shutdown' });
          socketPath = '';
          return;
        }
        if (options.muted === false) await request(host, '/command', { action: 'muted', value: false });
      })().finally(() => { starting = null; });
    }
    await starting;
  }

  // UI actions and lifecycle updates preserve ordering without waiting for video lookup.
  /** @param {Host} host @param {() => Promise<unknown>} action */
  function act(host, action) {
    queue = queue.then(async () => {
      if (stopped) return;
      try { await action(); error = ''; }
      catch (caught) { error = errorMessage(caught); }
      host.invalidate();
    });
    return queue;
  }

  /** @param {Host} host */
  async function sync(host) {
    if (socketPath) await request(host, '/command', { action: 'playing', value: playback.playing });
  }

  /** @param {Host} host */
  async function open(host) {
    await host.openPane({ id: PANE, title: 'YouTube · experimental', columns: 60, rows: 22 });
    playback.open = true;
    await sync(host);
  }

  /** A plugin's own close call need not traverse its own close hook.
   * @param {Host} host
   */
  async function hide(host) {
    playback.open = false;
    mounted = false;
    discardWaitingFrames();
    await sync(host).catch(() => undefined);
    await host.closePane({ id: PANE });
  }

  /** @param {Host} host @param {string} value */
  async function load(host, value) {
    const source = parseSource(value);
    input = source.url;
    await ensureBridge(host);
    if (stopped) return;
    await changeSource(host, { action: 'load', source: source.url });
    await sync(host);
    await poll(host);
  }

  on('session.start', async ($, e, next) => {
    const host = hostOf($);
    stopped = false;
    supported = e.surface === 'terminal' && e.isInteractive;
    await $.command.register({ name: 'youtube', description: 'Watch a YouTube video or playlist in a terminal pane',
      argumentHint: '[YouTube URL|open|close|play|pause|auto|next|previous|mute|unmute|stats]', immediate: true });
    if (supported && input) {
      void act(host, async () => { await open(host); await load(host, input); });
    }
    return next(e);
  });

  on('command.run', { command: 'youtube' }, async ($, e) => {
    const host = hostOf($);
    if (!supported) return { text: 'YouTube video requires Claude Code in a Kitty-graphics terminal (such as Kitty or Ghostty), on macOS or Linux.' };
    const args = e.args.trim();
    if (args === 'stats') {
      if (measurement) return { text: 'A playback sample is already running.' };
      measurement = { frames: 0, paints: 0, refused: 0, fetchMs: 0, paintMs: 0, gapMs: 0, lastFrameAt: Date.now() };
      try {
        const before = await request(host, '/metrics');
        if (!before.playing) return { text: 'Select Play, then run /youtube stats to measure five seconds of playback.' };
        measurement = { frames: 0, paints: 0, refused: 0, fetchMs: 0, paintMs: 0, gapMs: 0, lastFrameAt: Date.now() };
        const sample = measurement;
        // This wait is outside the control queue: Hide/Pause still work.
        await $.clock.sleep(5000);
        const after = await request(host, '/metrics');
        if (before.generation !== after.generation || !after.playing) {
          return { text: 'Playback changed during the sample. Select Play and run /youtube stats again.' };
        }
        const seconds = Math.max(0.001, (after.now - before.now) / 1000);
        /** @param {number} count */
        const rate = count => (count / seconds).toFixed(1);
        const fetchMs = Math.max(sample.fetchMs, polling ? Date.now() - fetchStartedAt : 0);
        const paintMs = Math.max(sample.paintMs, painting ? Date.now() - paintStartedAt : 0);
        const gapMs = Math.max(sample.gapMs, Date.now() - sample.lastFrameAt);
        return { text: [
          `Playback sample: ${seconds.toFixed(1)} s · target ${after.targetFps} fps`,
          `Decoded: ${rate(after.decodedFrames - before.decodedFrames)} fps · received: ${rate(sample.frames)} fps · accepted paints: ${rate(sample.paints)}/s`,
          `Transport: ${after.transport} · helper: ${after.platform}`,
          `Longest wait: fetch ${fetchMs} ms · paint ${paintMs} ms · received-frame gap ${gapMs} ms`,
          `Refused paints during sample: ${sample.refused}${lastPaintDenial ? ` · last refusal: ${lastPaintDenial}` : ''}`,
          'Accepted paints are Claude acknowledgments, not a physical display measurement.',
        ].join('\n') };
      } catch (caught) { return { text: `Playback diagnostics unavailable: ${errorMessage(caught)}` }; }
      finally { measurement = null; }
    }
    await act(host, async () => {
      if (args === 'close') { await hide(host); return; }
      await open(host);
      if (['play', 'pause', 'auto'].includes(args)) { playback.mode = args; await sync(host); }
      else if (args === 'next' || args === 'previous') {
        if (!socketPath) throw new Error('Load a video or playlist first: /youtube <YouTube URL>.');
        await changeSource(host, { action: 'select', index: state.index + (args === 'next' ? 1 : -1) });
      } else if (args === 'mute' || args === 'unmute') {
        await ensureBridge(host);
        await request(host, '/command', { action: 'muted', value: args === 'mute' });
      } else if (args && args !== 'open') await load(host, args);
      else if (!socketPath && input) await load(host, input);
      await poll(host);
    });
    return { text: error || (args === 'close' ? 'YouTube pane closed; playback paused.'
      : `YouTube pane opened · ${playback.mode} mode. Paste a video or playlist link in the pane.`) };
  });

  on('turn.start', ($, e, next) => {
    const host = hostOf($);
    playback.start(e.turnId);
    void act(host, () => sync(host));
    return next(e);
  });

  on('turn.complete', ($, e, next) => {
    const host = hostOf($);
    if (e.agentId !== undefined || e.turnId !== playback.turnId) return next(e);
    playback.complete(e);
    void act(host, () => sync(host));
    return next(e);
  });

  on('ui.close', { id: PANE }, async ($, e, next) => {
    const host = hostOf($);
    playback.open = false;
    mounted = false;
    discardWaitingFrames();
    // Do not enqueue here: close can run inside a queued command.
    await sync(host).catch(() => undefined);
    return next(e);
  });

  on('session.end', async ($, e, next) => {
    const host = hostOf($);
    stopped = true;
    discardWaitingFrames();
    timer?.cancel();
    await queue;
    if (socketPath) await request(host, '/command', { action: 'shutdown' }).catch(() => undefined);
    socketPath = '';
    sequence = -1;
    image = EMPTY_IMAGE;
    playback.open = false;
    playback.turnId = null;
    playback.mode = 'auto';
    mounted = false;
    return next(e);
  });

  on('ui.render', { component: 'Pane' }, ($, e, next) => {
    const host = hostOf($);
    if (e.requestId !== PANE) return next(e);
    const t = $.ui.resolve(e);
    if (e.surface !== 'terminal' || !('Image' in t)) {
      return t.Text({ children: 'Experimental video requires a Kitty-graphics terminal such as Kitty or Ghostty.' });
    }
    mounted = true;
    const columns = Math.min(100, Math.max(1, e.props.bodyColumns - 2));
    const rows = Math.max(1, Math.round(columns * 9 / 32));
    /** @param {string} key @param {string} label @param {() => Promise<unknown>} action */
    const button = (key, label, action) => t.Button({ key, label, onPress: () => { void act(host, action); } });
    /** @param {string} value */
    const mode = value => { playback.mode = value; return sync(host); };
    const entry = state.entries[state.index];
    const children = [
      t.Text({ bold: true, children: state.title || 'YouTube · experimental' }),
      t.Box({ flexDirection: 'row', children: [
        t.Text({ children: `${playback.turnId ? 'Claude is working' : 'Claude is idle'} · ${playback.mode} · ${state.status}` }),
        ...(playback.playing && state.status === 'playing' && socketPath && !stopped
          ? [t.Client({ key: 'video-heartbeat', module: './heartbeat.js', width: 1, height: 1 })] : []),
      ] }),
      t.Image({ key: 'video', source: image, columns, rows,
        alt: 'Video needs a terminal with Kitty graphics support. See README for setup.' }),
      t.Text({ children: entry ? `${state.index + 1}/${state.entries.length} · ${entry.title}` : 'Paste a YouTube video or playlist link below.' }),
      t.Box({ flexDirection: 'row', gap: 1, children: [
        button('play', 'Play', () => mode('play')),
        button('pause', 'Pause', () => mode('pause')),
        button('auto', 'Auto', () => mode('auto')),
        button('mute', state.muted ? 'Unmute' : 'Mute', async () => {
          await ensureBridge(host);
          await request(host, '/command', { action: 'muted', value: !state.muted });
          await poll(host);
        }),
      ] }),
      t.Box({ flexDirection: 'row', gap: 1, children: [
        button('previous', 'Previous', () => changeSource(host, { action: 'select', index: state.index - 1 })),
        button('next', 'Next', () => changeSource(host, { action: 'select', index: state.index + 1 })),
        button('retry', 'Reload', () => load(host, input)),
        button('hide', 'Hide', () => hide(host)),
      ] }),
      t.Input({ key: 'source', label: 'YouTube link', value: input, placeholder: 'Video or playlist URL',
        submitLabel: 'Load', onInput: value => { input = value; },
        onSubmit: value => { void act(host, () => load(host, value)); } }),
    ];
    if (state.entries.length) children.push(t.Select({ key: 'video-select', label: 'Video',
      value: String(state.index), options: state.entries.map((item, index) => ({ value: String(index), label: `${index + 1}. ${item.title}` })),
      onSelect: value => { void act(host, () => changeSource(host, { action: 'select', index: Number(value) })); },
    }));
    if (error || connectionError || state.error || state.audioError) {
      children.push(t.Text({ children: error || connectionError || state.error || state.audioError }));
    }
    children.push(t.Text({ dimColor: true, children: 'Auto follows the whole turn, including tools. Play/Pause override Auto.' }));
    return t.Box({ flexDirection: 'column', gap: 1, children });
  });
  return undefined;
};

