import { parsePlaylist, playlistUrl } from './playlist.js';

const VIDEO_ID = /^[A-Za-z0-9_-]{11}$/;
const HOSTS = new Set(['youtube.com', 'www.youtube.com', 'm.youtube.com', 'music.youtube.com', 'youtu.be']);

/**
 * Normalize a video or playlist. A list= link is a playlist even when it names
 * a video too; startVideo preserves that selection without forwarding tracking.
 * @param {unknown} input
 * @returns {{kind: 'video' | 'playlist', id: string, url: string, startVideo?: string}}
 */
export function parseSource(input) {
  if (typeof input !== 'string' || !input.trim()) throw new Error('Enter a YouTube video or playlist link.');
  const value = input.trim();
  if (VIDEO_ID.test(value)) return { kind: 'video', id: value, url: `https://www.youtube.com/watch?v=${value}` };
  if (/^[A-Za-z0-9_-]{10,150}$/.test(value)) {
    return { kind: 'playlist', id: parsePlaylist(value), url: playlistUrl(value) };
  }
  let url;
  try { url = new URL(value); } catch { throw new Error('Enter a complete YouTube video or playlist URL.'); }
  if (!['https:', 'http:'].includes(url.protocol) || !HOSTS.has(url.hostname) || url.username || url.password || url.port) {
    throw new Error('Use a youtube.com or youtu.be video or playlist URL.');
  }
  const parts = url.pathname.split('/').filter(Boolean);
  let video = '';
  if (url.hostname === 'youtu.be' && parts.length === 1) video = parts[0];
  else if (['shorts', 'live', 'embed'].includes(parts[0]) && parts.length === 2) video = parts[1];
  else if (url.pathname === '/watch') {
    const videos = url.searchParams.getAll('v');
    if (videos.length > 1) throw new Error('Use a link with only one video ID.');
    video = videos[0] ?? '';
  }
  if (video && !VIDEO_ID.test(video)) throw new Error('The YouTube video ID is invalid.');
  if (url.searchParams.getAll('list').length) {
    const id = parsePlaylist(value);
    return { kind: 'playlist', id,
      url: video ? `https://www.youtube.com/watch?v=${video}&list=${id}` : playlistUrl(id),
      ...(video ? { startVideo: video } : {}),
    };
  }
  if (!video) throw new Error('This link does not identify a YouTube video or playlist.');
  return { kind: 'video', id: video, url: `https://www.youtube.com/watch?v=${video}` };
}

