/** Main-turn identity prevents subagent and stale completion events pausing video. */
export class PlaybackMode {
  mode = 'auto';
  /** @type {string | null} */
  turnId = null;
  open = false;

  /** @param {string} turnId */
  start(turnId) { this.turnId = turnId; }

  /** @param {{turnId: string, agentId?: string}} event */
  complete(event) {
    if (event.agentId === undefined && event.turnId === this.turnId) this.turnId = null;
  }

  get playing() {
    return this.open && (this.mode === 'play' || (this.mode === 'auto' && this.turnId !== null));
  }
}

