// Keep Claude's idle paint clock moving without invalidating the whole pane.
// Technique described by Gábor Mészáros (Reporails), "Claude Code mods: but
// does it run Doom?": https://dev.to/reporails/claude-code-mods-but-does-it-run-doom-2mma
// This Client exists only during playback; unmounting cancels its timer.

/** @type {import('claude-code').ClientModule<null, boolean>} */
const Heartbeat = (_props, surface) => {
  if (surface.state === undefined) {
    surface.setState(false);
    surface.every(30, () => surface.setState(!surface.state));
  }
  // Different glyphs, both visually blank, so the renderer sees a change.
  return surface.elements.Text({ children: surface.state ? '\u2800' : ' ' });
};

export default Heartbeat;

