const PLAYLIST_ID = /^[A-Za-z0-9_-]{10,150}$/;
const YOUTUBE_HOSTS = new Set([
  'youtube.com',
  'www.youtube.com',
  'm.youtube.com',
  'music.youtube.com',
  'youtu.be',
]);

/**
 * Accept a playlist ID or an explicit YouTube URL containing one.
 * Return only the ID: tracking parameters and arbitrary hosts never reach a player.
 * This validates syntax; availability is determined by YouTube at playback time.
 * @param {unknown} input
 */
export function parsePlaylist(input) {
  if (typeof input !== 'string') throw new Error('Enter a YouTube playlist URL or ID.');
  const value = input.trim();
  if (!value) throw new Error('Enter a YouTube playlist URL or ID.');
  if (PLAYLIST_ID.test(value)) return value;

  let url;
  try {
    url = new URL(value);
  } catch {
    throw new Error('Enter a complete YouTube playlist URL or a playlist ID.');
  }
  if (
    !['https:', 'http:'].includes(url.protocol) ||
    !YOUTUBE_HOSTS.has(url.hostname) ||
    url.username || url.password || url.port
  ) {
    throw new Error('Use a youtube.com or youtu.be playlist URL.');
  }
  const ids = url.searchParams.getAll('list');
  if (ids.length !== 1 || !PLAYLIST_ID.test(ids[0])) {
    throw new Error('The YouTube URL must contain one valid list= playlist ID.');
  }
  return ids[0];
}

/** Produce a canonical public link from validated input. @param {unknown} input */
export function playlistUrl(input) {
  return `https://www.youtube.com/playlist?list=${parsePlaylist(input)}`;
}

